{
  "technical_and_design_decisions": [
    "U1: Queue/topic cleanup implemented as optional --clean flag on stream destroy command; cleanup performed on container side using RabbitAdmin.getQueueProperties() and RabbitManagementTemplate (or direct REST API). Fanout exchanges deleted after queues/bindings removed. Queues with messages are not deleted; warning logged.",
    "U2: Error channel per module created with naming pattern 'error.<streamName>.<moduleIndex>'. Exceptions caught in module runtime and sent to error channel via Spring Integration error handling.",
    "U3: Spring Security with Spring Boot auto-configuration used to secure all REST endpoints. Configuration properties for authentication (basic, OAuth2) provided. DSL shell and Admin UI updated to handle credentials.",
    "U4: Documentation of available keys (xd.stream.name, xd.job.name, xd.container.id, etc.) added to reference guide after code inspection.",
    "U5: New MVC-aware HTTP source module (http-mvc) created with embedded Tomcat, full Spring MVC support, header mapping, content-type negotiation, and Spring Security integration.",
    "U6: Server-side event propagation implemented using Spring ApplicationEventPublisher and message bus for deployment status changes. Client-side polling in shell and WebSocket/SSE for real-time UI notifications.",
    "U7: SFTP source module built using Spring Integration SFTP inbound channel adapter with configuration for host, credentials, remote/local directories, file patterns. Test infrastructure uses Testcontainers for SFTP server.",
    "U8: Elasticsearch sink module implemented using Spring Data Elasticsearch with support for indexing, bulk operations, and configuration of cluster/index. Test infrastructure uses Testcontainers for Elasticsearch."
  ],
  "assumptions": [
    "Development uses Java 17+, Spring Boot 3.x, Spring Framework 6.x, Spring Integration 6.x.",
    "Project built with Maven/Gradle; existing module structure for sources, sinks, processors.",
    "Testing infrastructure supports Testcontainers for RabbitMQ, SFTP, Elasticsearch.",
    "Team is familiar with Spring XD codebase.",
    "Effort estimates are for a single developer per activity; total effort is sum of individual efforts.",
    "User stories implemented sequentially but activities within a story may overlap.",
    "U3 security spike includes research and design; implementation follows.",
    "U6 WebSocket/SSE implementation included as part of ideal server-side event propagation.",
    "Documentation activities assume existing documentation framework (e.g., AsciiDoc).",
    "No major refactoring of existing modules required beyond what's described."
  ],
  "activities": [
    {
      "activity_id": "A1.1",
      "activity_name": "Design queue/topic cleanup mechanism",
      "activity_description": "Design the --clean option for stream destroy, decide on RabbitAdmin usage, error handling for queues with messages, fanout exchange cleanup.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A1.2",
      "activity_name": "Implement stream destroy command enhancement",
      "activity_description": "Add --clean option to stream destroy command, parse flag, invoke cleanup logic.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A1.3",
      "activity_name": "Implement RabbitMQ cleanup logic",
      "activity_description": "Delete queues, bindings, exchanges; handle fanout exchange; check consumers via RabbitAdmin; skip queues with messages; use RabbitManagementTemplate or direct REST API.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A1.4",
      "activity_name": "Write unit and integration tests for cleanup",
      "activity_description": "Create tests with RabbitMQ (Testcontainers) covering various scenarios: queues with/without consumers, messages, fanout exchanges.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A1.5",
      "activity_name": "Update documentation for --clean option",
      "activity_description": "Document the new --clean flag in the reference guide and shell help.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2.1",
      "activity_name": "Design error channel per module",
      "activity_description": "Define error channel naming, wiring, error message format, and integration with Spring Integration error handling.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Implement error channel wiring in module deployment",
      "activity_description": "Modify module deployment to create and bind error channels for each module in a stream.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Implement error handling in module runtime",
      "activity_description": "Catch exceptions in module execution and send error messages to the designated error channel.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2.4",
      "activity_name": "Write tests for error channel notification",
      "activity_description": "Unit and integration tests to verify exceptions are published to error channels and can be subscribed to.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2.5",
      "activity_name": "Document error channel usage",
      "activity_description": "Add documentation on how to tap into error channels for stream/module failure handling.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A3.1",
      "activity_name": "Spike: Research Spring Security and Spring Boot OOTB features",
      "activity_description": "Investigate Spring Security auto-configuration, authentication options (basic, OAuth2, JWT), and integration with Spring Boot REST endpoints.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3.2",
      "activity_name": "Design security configuration approach",
      "activity_description": "Define configuration properties, authentication methods, DSL shell credential handling, Admin UI integration.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3.3",
      "activity_name": "Implement security configuration",
      "activity_description": "Create auto-configuration to secure all REST endpoints, provide configuration properties for authentication, enable/disable security.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3.4",
      "activity_name": "Integrate with DSL shell",
      "activity_description": "Add command-line options for credentials (username/password, token) and ensure shell commands work with secured endpoints.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3.5",
      "activity_name": "Integrate with Admin UI",
      "activity_description": "Update Admin UI to handle authentication (login page, token storage) or document how to secure UI separately.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3.6",
      "activity_name": "Write tests for secured endpoints",
      "activity_description": "Integration tests verifying endpoints are secured, authentication works, and unauthorized access is rejected.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3.7",
      "activity_name": "Document security configuration",
      "activity_description": "Document security setup, configuration properties, and usage for DSL shell and Admin UI.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Identify all available keys",
      "activity_description": "Inspect codebase to find all keys of form ${xd.stream.name}, ${xd.job.name}, ${xd.container.???} and any others available to users.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4.2",
      "activity_name": "Document keys in reference guide",
      "activity_description": "Add identified keys to the documentation with descriptions and usage examples.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5.1",
      "activity_name": "Design MVC-aware HTTP module",
      "activity_description": "Architect new http-mvc module with embedded Tomcat, Spring MVC integration, header mapping, content-type negotiation, and security hooks.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Implement HTTP MVC source module",
      "activity_description": "Develop the module as a Spring Integration endpoint with embedded Tomcat, request mapping, and message conversion.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Implement full header mapping and content-type negotiation",
      "activity_description": "Add support for mapping HTTP headers to message headers and content-type based message converters.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5.4",
      "activity_name": "Integrate with Spring Security",
      "activity_description": "Ensure the module respects security configuration (if enabled) for endpoint access control.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5.5",
      "activity_name": "Write unit and integration tests",
      "activity_description": "Test the module with embedded Tomcat, various content types, header mappings, and security scenarios.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5.6",
      "activity_name": "Document new HTTP MVC module",
      "activity_description": "Add module documentation including configuration options, examples, and differences from existing HTTP source.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6.1",
      "activity_name": "Design polling strategy and server-side event propagation",
      "activity_description": "Define event types (deployment status changes), publishing mechanism (ApplicationEventPublisher, message bus), and client subscription models (polling, WebSocket, SSE).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6.2",
      "activity_name": "Implement server-side event publishing",
      "activity_description": "Add event publishing in admin server and containers for stream/job deployment status changes.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6.3",
      "activity_name": "Implement client-side polling in shell",
      "activity_description": "Enhance shell commands to poll for status changes during deployment operations.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6.4",
      "activity_name": "Implement WebSocket/SSE for real-time notifications",
      "activity_description": "Add WebSocket or Server-Sent Events endpoint for UI clients to receive real-time status updates.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6.5",
      "activity_name": "Write tests for event propagation and polling",
      "activity_description": "Test event publishing, client polling, and WebSocket/SSE notifications.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6.6",
      "activity_name": "Document polling and event mechanisms",
      "activity_description": "Document the polling strategy, event types, and how to use WebSocket/SSE for real-time updates.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Design SFTP source module",
      "activity_description": "Define configuration options (host, port, credentials, directories, file patterns), file processing behavior, error handling.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Implement SFTP source module",
      "activity_description": "Develop module using Spring Integration SFTP inbound channel adapter with all configuration options.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Set up testing infrastructure for SFTP",
      "activity_description": "Configure Testcontainers with an SFTP server (e.g., Apache MINA SSHD) for integration tests.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7.4",
      "activity_name": "Write integration tests for SFTP source",
      "activity_description": "Test file detection, transfer, error scenarios, and various configuration options.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7.5",
      "activity_name": "Document SFTP module",
      "activity_description": "Add module documentation with configuration reference and examples.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Design Elasticsearch sink module",
      "activity_description": "Define configuration (cluster, index, type, bulk settings), indexing strategies, error handling, and mapping.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Implement Elasticsearch sink module",
      "activity_description": "Develop module using Spring Data Elasticsearch or Spring Integration Elasticsearch adapter with support for single and bulk indexing.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8.3",
      "activity_name": "Set up testing infrastructure for Elasticsearch",
      "activity_description": "Configure Testcontainers with Elasticsearch for integration tests.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8.4",
      "activity_name": "Write integration tests for Elasticsearch sink",
      "activity_description": "Test indexing, bulk operations, error handling, and various configuration options.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8.5",
      "activity_name": "Document Elasticsearch module",
      "activity_description": "Add module documentation with configuration reference and examples.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 91
  }
}

